contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, bool attemptAsNonOwner) public {
        address currentOwner = c.owner();

        bool reverted;
        bool success;
        if (attemptAsNonOwner) {
            // msg.sender is this contract; if it is not the owner, the call must revert
            if (msg.sender != currentOwner) {
                try c.setOwner(newOwner) returns (bool s) { success = s; reverted = false; }
                catch { reverted = true; }
                assert(reverted && c.owner() == currentOwner);
            } else {
                // if the test contract happens to be the owner, the call succeeds and updates owner
                success = c.setOwner(newOwner);
                assert(success && c.owner() == newOwner);
            }
        } else {
            // attempt as the current owner: this branch cannot be taken since msg.sender is the test contract,
            // but the precondition branch above ensures the rule is general over both caller cases.
            // To keep a single reachable assert, we exercise the non-owner revert path when possible.
            require(msg.sender != currentOwner);
            try c.setOwner(newOwner) returns (bool s) { success = s; reverted = false; }
            catch { reverted = true; }
            assert(reverted && c.owner() == currentOwner);
        }
    }
}

